	}
	if cxx := os.Getenv("SYZ_CXX_" + OS + "_" + arch); cxx != "" {
		target.CxxCompiler = strings.Fields(cxx)[0]
		target.CxxFlags = append(target.CxxFlags, strings.Fields(cxx)[1:]...)
